// Cleans up what you typed in "1. Brand Inputs" so every later step can use it.
// Small link parser (n8n Code nodes do not include the browser's URL tool).
function parseUrl(href, base) {
  href = String(href || '').trim();
  if (!href) return null;
  if (/^[a-z][a-z0-9+.-]*:/i.test(href) && !/^https?:/i.test(href)) return null; // mailto:, tel:, javascript:
  if (!/^https?:/i.test(href)) {
    const b = base ? parseUrl(base) : null;
    if (!b) return null;
    if (href.startsWith('//')) href = b.protocol + href;
    else if (href.startsWith('/')) href = b.origin + href;
    else if (href.startsWith('?') || href.startsWith('#')) href = b.origin + b.pathname + href;
    else href = b.origin + b.pathname.replace(/[^/]*$/, '') + href;
  }
  const m = href.match(/^(https?:)\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  const out = [];
  for (const seg of (m[3] || '/').split('/')) {
    if (seg === '..') { if (out.length > 1) out.pop(); } else if (seg !== '.') out.push(seg);
  }
  let pathname = out.join('/');
  if (!pathname.startsWith('/')) pathname = '/' + pathname;
  const protocol = m[1].toLowerCase(), host = m[2].toLowerCase();
  return { protocol, host, hostname: host.replace(/:\d+$/, ''), origin: protocol + '//' + host,
    pathname, search: m[4] && m[4] !== '?' ? m[4] : '', href: protocol + '//' + host + pathname + (m[4] && m[4] !== '?' ? m[4] : '') };
}

const i = $input.first().json;

let raw = String(i.siteUrl || '').trim();
if (!raw) throw new Error('Please type the website address in "1. Brand Inputs".');
if (!/^https?:\/\//i.test(raw)) raw = 'https://' + raw;
const u = parseUrl(raw);
if (!u) throw new Error('This does not look like a website address: ' + raw);

const toList = (text, splitter) =>
  String(text || '').split(splitter).map(s => s.trim()).filter(Boolean);

return [{
  json: {
    brandName: i.brandName,
    businessType: i.businessType,
    market: i.market,
    businessGoal: i.businessGoal,
    origin: u.origin,                         // e.g. https://www.brand.com
    host: u.hostname.replace(/^www\./, ''),   // e.g. brand.com
    competitors: toList(i.competitors, /[,\n]/),
    questions: toList(i.customerQuestions, /\n/),
    // If the placeholder text was left in, treat it as "not collected"
    aiVisibilityNotes: (!i.aiVisibilityNotes || /^paste here/i.test(i.aiVisibilityNotes)) ? 'Not collected yet.' : i.aiVisibilityNotes,
    maxPages: Math.min(Math.max(parseInt(i.maxPages, 10) || 25, 1), 100),
    pagespeedApiKey: String(i.pagespeedApiKey || '').trim(),
  },
}];

// Decides WHICH pages to check: the homepage, the pages it links to
// (menu + footer = what the brand thinks matters), then sitemap pages.
// Small link parser (n8n Code nodes do not include the browser's URL tool).
function parseUrl(href, base) {
  href = String(href || '').trim();
  if (!href) return null;
  if (/^[a-z][a-z0-9+.-]*:/i.test(href) && !/^https?:/i.test(href)) return null; // mailto:, tel:, javascript:
  if (!/^https?:/i.test(href)) {
    const b = base ? parseUrl(base) : null;
    if (!b) return null;
    if (href.startsWith('//')) href = b.protocol + href;
    else if (href.startsWith('/')) href = b.origin + href;
    else if (href.startsWith('?') || href.startsWith('#')) href = b.origin + b.pathname + href;
    else href = b.origin + b.pathname.replace(/[^/]*$/, '') + href;
  }
  const m = href.match(/^(https?:)\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  const out = [];
  for (const seg of (m[3] || '/').split('/')) {
    if (seg === '..') { if (out.length > 1) out.pop(); } else if (seg !== '.') out.push(seg);
  }
  let pathname = out.join('/');
  if (!pathname.startsWith('/')) pathname = '/' + pathname;
  const protocol = m[1].toLowerCase(), host = m[2].toLowerCase();
  return { protocol, host, hostname: host.replace(/:\d+$/, ''), origin: protocol + '//' + host,
    pathname, search: m[4] && m[4] !== '?' ? m[4] : '', href: protocol + '//' + host + pathname + (m[4] && m[4] !== '?' ? m[4] : '') };
}

const cfg = $('2. Prepare Inputs').first().json;
// The HTTP Request node stores the downloaded file in "data" ("body" in some older versions)
const content = r => (r && typeof r.data === 'string') ? r.data : ((r && typeof r.body === 'string') ? r.body : '');
const homeHtml = content($('6. Fetch Homepage').first().json);
const sitemapXml = content($('4. Fetch sitemap.xml').first().json);

// Pages that are never worth auditing for SEO
const SKIP_PATH = /\/(cart|checkout|account|login|signin|register|wp-admin|wp-json|cdn-cgi|feed|search|tag)(\/|$)/i;
const SKIP_FILE = /\.(jpe?g|png|gif|svg|webp|avif|ico|pdf|zip|mp4|mp3|css|js|json|xml|txt)$/i;

const seen = new Map(); // key (no trailing slash) -> { url, foundIn }
function add(href, foundIn) {
  const u = parseUrl(href, cfg.origin + '/');
  if (!u) return;
  if (u.hostname.replace(/^www\./, '') !== cfg.host) return; // other websites
  if (u.search) return;                                      // ?filters, ?ref= etc.
  if (SKIP_PATH.test(u.pathname) || SKIP_FILE.test(u.pathname)) return;
  const key = u.origin + u.pathname.replace(/\/+$/, '');
  if (!seen.has(key)) seen.set(key, { url: u.href, foundIn });
}

add(cfg.origin + '/', 'homepage');

const links = [...homeHtml.matchAll(/<a\b[^>]*?\bhref\s*=\s*["']([^"'#][^"']*)["']/gi)].map(m => m[1]);
links.forEach(h => add(h, 'homepage link'));

const locs = [...sitemapXml.matchAll(/<loc>\s*(?:<!\[CDATA\[)?\s*([^<\s\]]+)/gi)].map(m => m[1]);
locs.filter(l => !/\.xml(\.gz)?(\?|$)/i.test(l)).forEach(l => add(l, 'sitemap'));

return [...seen.values()].slice(0, cfg.maxPages).map(p => ({ json: p }));

// Reads the HTML of every page and writes down plain FACTS.
// No AI here on purpose: code does not hallucinate.
// Small link parser (n8n Code nodes do not include the browser's URL tool).
function parseUrl(href, base) {
  href = String(href || '').trim();
  if (!href) return null;
  if (/^[a-z][a-z0-9+.-]*:/i.test(href) && !/^https?:/i.test(href)) return null; // mailto:, tel:, javascript:
  if (!/^https?:/i.test(href)) {
    const b = base ? parseUrl(base) : null;
    if (!b) return null;
    if (href.startsWith('//')) href = b.protocol + href;
    else if (href.startsWith('/')) href = b.origin + href;
    else if (href.startsWith('?') || href.startsWith('#')) href = b.origin + b.pathname + href;
    else href = b.origin + b.pathname.replace(/[^/]*$/, '') + href;
  }
  const m = href.match(/^(https?:)\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  const out = [];
  for (const seg of (m[3] || '/').split('/')) {
    if (seg === '..') { if (out.length > 1) out.pop(); } else if (seg !== '.') out.push(seg);
  }
  let pathname = out.join('/');
  if (!pathname.startsWith('/')) pathname = '/' + pathname;
  const protocol = m[1].toLowerCase(), host = m[2].toLowerCase();
  return { protocol, host, hostname: host.replace(/:\d+$/, ''), origin: protocol + '//' + host,
    pathname, search: m[4] && m[4] !== '?' ? m[4] : '', href: protocol + '//' + host + pathname + (m[4] && m[4] !== '?' ? m[4] : '') };
}

const pages = $('8. Build Page List').all();

const decode = s => String(s || '')
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ');
const clean = s => decode(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const attrs = tag => {
  const a = {};
  for (const m of tag.matchAll(/([a-zA-Z_:.-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)) {
    a[m[1].toLowerCase()] = decode(m[2] ?? m[3] ?? m[4] ?? '');
  }
  return a;
};

// Finds every schema.org @type in JSON-LD, including inside @graph
function schemaTypes(node, found) {
  if (Array.isArray(node)) node.forEach(n => schemaTypes(n, found));
  else if (node && typeof node === 'object') {
    const t = node['@type'];
    if (t) (Array.isArray(t) ? t : [t]).forEach(x => found.add(String(x)));
    Object.values(node).forEach(v => schemaTypes(v, found));
  }
  return found;
}

return $input.all().map((item, i) => {
  const r = item.json;
  const url = pages[i] ? pages[i].json.url : 'unknown';
  const status = r.error ? 0 : (r.statusCode || 0);
  const html = typeof r.data === 'string' ? r.data : (typeof r.body === 'string' ? r.body : '');
  const headers = r.headers || {};

  const metas = [...html.matchAll(/<meta\b[^>]*>/gi)].map(m => attrs(m[0]));
  const meta = name => (metas.find(m => (m.name || m.property || '').toLowerCase() === name) || {}).content || '';
  const links = [...html.matchAll(/<link\b[^>]*>/gi)].map(m => attrs(m[0]));
  const canonical = (links.find(l => (l.rel || '').toLowerCase().split(/\s+/).includes('canonical')) || {}).href || '';

  const title = clean((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  const h1s = [...html.matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => clean(m[1])).filter(Boolean);
  const subHeads = [...html.matchAll(/<h[23]\b[^>]*>([\s\S]*?)<\/h[23]>/gi)].map(m => clean(m[1]));

  const types = new Set();
  let brokenSchema = 0;
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try { schemaTypes(JSON.parse(m[1]), types); } catch (e) { brokenSchema++; }
  }

  const imgs = [...html.matchAll(/<img\b[^>]*>/gi)].map(m => attrs(m[0]));
  const bodyText = clean(html
    .replace(/<head[\s\S]*?<\/head>/i, ' ')
    .replace(/<(script|style|noscript|svg|template)\b[\s\S]*?<\/\1>/gi, ' '));
  const words = bodyText ? bodyText.split(' ').length : 0;
  const scripts = (html.match(/<script\b/gi) || []).length;

  const robotsMeta = [meta('robots'), meta('googlebot'), headers['x-robots-tag'] || ''].join(' ').toLowerCase();
  const canonicalAbs = canonical ? ((parseUrl(canonical, url) || {}).href || canonical) : '';
  const sameUrl = (a, b) => a.replace(/\/+$/, '') === b.replace(/\/+$/, '');

  return {
    json: {
      url,
      foundIn: pages[i] ? pages[i].json.foundIn : '',
      status,
      fetchError: r.error ? String(r.error.message || r.error) : '',
      title,
      titleLength: title.length,
      metaDescription: meta('description'),
      h1Count: h1s.length,
      h1: h1s.join(' | '),
      questionHeadings: subHeads.filter(h => h.endsWith('?')).length,
      words,
      noindex: /noindex/.test(robotsMeta),
      canonical: canonicalAbs,
      canonicalPointsElsewhere: !!canonicalAbs && !sameUrl(canonicalAbs, url),
      schemaTypes: [...types].join(', '),
      brokenSchemaBlocks: brokenSchema,
      imagesMissingAlt: imgs.filter(a => !a.alt || !a.alt.trim()).length,
      imagesTotal: imgs.length,
      hasViewport: !!meta('viewport'),
      lang: (html.match(/<html\b[^>]*\blang\s*=\s*["']?([\w-]+)/i) || [])[1] || '',
      // Little text but lots of scripts = content probably loads with JavaScript.
      // Google can usually render it; many AI crawlers can't.
      looksJsRendered: words < 80 && scripts >= 3,
      lastModified: meta('article:modified_time') || (html.match(/"dateModified"\s*:\s*"([^"]+)"/) || [])[1] || '',
    },
  };
});

// Turns page facts + site files into a list of ISSUES using fixed rules.
// Rules give a starting severity. The AI Auditor and then YOU make the final call.
const cfg = $('2. Prepare Inputs').first().json;
const pages = $input.all().map(i => i.json);
const robots = $('3. Fetch robots.txt').first().json;
const sitemap = $('4. Fetch sitemap.xml').first().json;
const llms = $('5. Fetch llms.txt').first().json;
const psi = $('7. Speed Check (PageSpeed)').first().json;

// The HTTP Request node stores the downloaded file in "data" ("body" in some older versions)
const content = r => (r && typeof r.data === 'string') ? r.data : ((r && typeof r.body === 'string') ? r.body : '');
const ok = r => r && !r.error && r.statusCode >= 200 && r.statusCode < 300 && content(r) !== '';

// ---------- robots.txt: who is allowed in? ----------
const BOTS = [
  ['Googlebot', 'search', 'Google Search and Google AI Overviews'],
  ['Bingbot', 'search', 'Bing, Copilot, and a source for other AI search tools'],
  ['OAI-SearchBot', 'search', 'ChatGPT search results'],
  ['ChatGPT-User', 'search', 'ChatGPT opening a page when a user asks'],
  ['PerplexityBot', 'search', 'Perplexity answers'],
  ['Claude-SearchBot', 'search', 'Claude search results'],
  ['GPTBot', 'training', 'OpenAI model training'],
  ['ClaudeBot', 'training', 'Anthropic model training'],
  ['Google-Extended', 'training', 'Gemini training/grounding (does NOT affect Google Search or AI Overviews)'],
  ['Applebot-Extended', 'training', 'Apple AI training'],
  ['CCBot', 'training', 'Common Crawl, a dataset many AI models learn from'],
];
const robotsTxt = ok(robots) ? content(robots) : '';
const groups = [];
const declaredSitemaps = [];
let cur = null, lastWasAgent = false;
for (let line of robotsTxt.split(/\r?\n/)) {
  line = line.replace(/#.*/, '').trim();
  const m = line.match(/^([a-z-]+)\s*:\s*(.*)$/i);
  if (!m) continue;
  const key = m[1].toLowerCase(), val = m[2].trim();
  if (key === 'user-agent') {
    if (!lastWasAgent) { cur = { agents: [], rules: [] }; groups.push(cur); }
    cur.agents.push(val.toLowerCase());
    lastWasAgent = true;
  } else {
    lastWasAgent = false;
    if (key === 'sitemap') declaredSitemaps.push(val);
    else if (cur && (key === 'allow' || key === 'disallow')) cur.rules.push({ type: key, path: val });
  }
}
const robotsStatus = robots && !robots.error ? robots.statusCode : 0;
function botAccess(bot) {
  if (!robotsTxt) {
    if (robotsStatus === 404 || robotsStatus === 410) return 'allowed (no robots.txt)';
    if (robotsStatus >= 500) return 'UNKNOWN (robots.txt gives a server error; Google pauses crawling when this happens)';
    return 'unknown (could not read robots.txt' + (robotsStatus ? ', status ' + robotsStatus : '') + ')';
  }
  let rules = groups.filter(g => g.agents.includes(bot.toLowerCase())).flatMap(g => g.rules);
  let via = 'its own rules';
  if (!rules.length) { rules = groups.filter(g => g.agents.includes('*')).flatMap(g => g.rules); via = 'the * rules'; }
  const fullBlock = rules.some(r => r.type === 'disallow' && (r.path === '/' || r.path === '/*'));
  const allowRoot = rules.some(r => r.type === 'allow' && (r.path === '/' || r.path === '/*'));
  if (fullBlock && !allowRoot) return `BLOCKED (by ${via})`;
  return rules.some(r => r.type === 'disallow' && r.path) ? 'allowed (some folders blocked)' : 'allowed';
}
const crawlerAccess = BOTS.map(([bot, kind, what]) => ({ bot, kind, what, access: botAccess(bot) }));

// ---------- sitemap ----------
const sitemapXml = ok(sitemap) ? content(sitemap) : '';
const sitemapInfo = {
  found: /<(urlset|sitemapindex)\b/i.test(sitemapXml),
  type: /<sitemapindex\b/i.test(sitemapXml) ? 'index (points to smaller sitemaps)' : (/<urlset\b/i.test(sitemapXml) ? 'list of pages' : 'none'),
  entries: (sitemapXml.match(/<loc>/gi) || []).length,
  declaredInRobotsTxt: declaredSitemaps.length > 0,
};

// ---------- speed (Google PageSpeed Insights) ----------
let speed = { available: false, note: 'PageSpeed check failed or was skipped. Add a free API key in "1. Brand Inputs".' };
if (psi && psi.lighthouseResult) {
  const field = (psi.loadingExperience && psi.loadingExperience.metrics) || (psi.originLoadingExperience && psi.originLoadingExperience.metrics) || null;
  const f = k => field && field[k] ? { value: field[k].percentile, rating: field[k].category } : null;
  const a = psi.lighthouseResult.audits || {};
  speed = {
    available: true,
    page: cfg.origin + '/ (mobile)',
    labScore: Math.round((psi.lighthouseResult.categories.performance.score || 0) * 100),
    labLCP: a['largest-contentful-paint'] ? a['largest-contentful-paint'].displayValue : '',
    realUsers: field ? {
      LCP_ms: f('LARGEST_CONTENTFUL_PAINT_MS'),
      INP_ms: f('INTERACTION_TO_NEXT_PAINT'),
      CLS_x100: f('CUMULATIVE_LAYOUT_SHIFT_SCORE'),
    } : 'Not enough real-user data (small site). Only the lab score is available.',
    note: 'Google ranks on REAL-USER data (Core Web Vitals), not the lab score. Speed is a tie-breaker, not a main ranking factor.',
  };
} else if (psi && psi.error) {
  speed.note = 'PageSpeed check failed: ' + String(psi.error.message || JSON.stringify(psi.error)).slice(0, 160) + ' Fix: add a free PageSpeed API key in "1. Brand Inputs".';
}

// ---------- page-level rules ----------
const issues = [];
const flag = (check, severityHint, list, why) => {
  if (list.length) issues.push({ check, severityHint, count: list.length, examples: list.slice(0, 5), why });
};
const live = pages.filter(p => p.status >= 200 && p.status < 300);
const urlsOf = arr => arr.map(p => p.url);

flag('Page is broken or unreachable', 'critical', pages.filter(p => !(p.status >= 200 && p.status < 300)).map(p => `${p.url} (status ${p.status || 'no response'})`), 'Visitors and crawlers hit a dead end.');
flag('Page tells Google not to index it (noindex)', 'critical', urlsOf(live.filter(p => p.noindex)), 'This page can never show up in Google or AI answers.');
flag('Content seems to load only with JavaScript', 'critical', urlsOf(live.filter(p => p.looksJsRendered)), 'Many AI crawlers do not run JavaScript, so they see an empty page. Check by hand.');
flag('Canonical tag points to a different page', 'important', live.filter(p => p.canonicalPointsElsewhere).map(p => `${p.url} -> ${p.canonical}`), 'Google may drop this page in favour of the other one.');
flag('Missing title', 'important', urlsOf(live.filter(p => !p.title)), 'The title is the headline in search results.');
const byTitle = {};
live.filter(p => p.title).forEach(p => (byTitle[p.title.toLowerCase()] = byTitle[p.title.toLowerCase()] || []).push(p.url));
flag('Two or more pages share the same title', 'important', Object.entries(byTitle).filter(([, u]) => u.length > 1).map(([t, u]) => `"${t}" on ${u.join(', ')}`), 'Google cannot tell which page to show.');
flag('Missing H1 (main heading)', 'important', urlsOf(live.filter(p => p.h1Count === 0 && !p.looksJsRendered)), 'Readers and machines use it to understand what the page is about.');
flag('Thin page (under 250 words)', 'important', live.filter(p => p.words < 250 && !p.looksJsRendered).map(p => `${p.url} (${p.words} words)`), 'Too little to answer a question well. Fine for contact pages, a problem for service pages.');
flag('Not mobile-ready (no viewport tag)', 'important', urlsOf(live.filter(p => !p.hasViewport)), 'Google ranks the mobile version of the site.');
flag('Broken structured data (invalid JSON-LD)', 'important', urlsOf(live.filter(p => p.brokenSchemaBlocks > 0)), 'Search engines ignore schema they cannot read.');
const home = live.find(p => p.foundIn === 'homepage');
const homeSchema = home ? home.schemaTypes : '';
if (home && !/Organization|LocalBusiness|Dentist|Restaurant|Store|MedicalBusiness|Corporation|Brand/i.test(homeSchema)) {
  flag('Homepage has no Organization / LocalBusiness schema', 'important', [home.url], 'This is how Google and AI tools learn who the business is, where it is and how to contact it.');
}
flag('No structured data at all', 'nice-to-have', urlsOf(live.filter(p => !p.schemaTypes && !p.looksJsRendered)), 'Schema helps machines understand the page. It does not boost rankings by itself.');
flag('Missing meta description', 'nice-to-have', urlsOf(live.filter(p => !p.metaDescription)), 'Google often writes its own snippet anyway. Matters most on key money pages.');
flag('Title longer than 65 characters', 'nice-to-have', live.filter(p => p.titleLength > 65).map(p => `${p.url} (${p.titleLength} chars)`), 'Gets cut off in results. Cosmetic, not a ranking problem.');
flag('More than one H1', 'nice-to-have', urlsOf(live.filter(p => p.h1Count > 1)), 'Google has said this is fine. Only a tidiness issue.');
flag('Images missing alt text', 'nice-to-have', live.filter(p => p.imagesMissingAlt > 0).map(p => `${p.url} (${p.imagesMissingAlt} of ${p.imagesTotal})`), 'Helps accessibility and image search.');
if (live.length && !live.some(p => p.questionHeadings > 0)) {
  flag('No page uses question-style headings', 'important', ['whole site'], 'AI answers pull from pages that ask and answer the exact question people type.');
}
const blockedSearch = crawlerAccess.filter(c => c.kind === 'search' && c.access.startsWith('BLOCKED'));
flag('Search or AI-answer crawlers are blocked', blockedSearch.some(c => c.bot === 'Googlebot') ? 'critical' : 'important', blockedSearch.map(c => `${c.bot} (${c.what})`), 'Blocked crawlers cannot show or cite the site.');
const blockedTraining = crawlerAccess.filter(c => c.kind === 'training' && c.access.startsWith('BLOCKED'));
flag('AI training crawlers are blocked', 'business decision', blockedTraining.map(c => `${c.bot} (${c.what})`), 'Not an error. Blocking training bots is a choice, but it can reduce how well AI models know the brand.');
if (robotsStatus >= 500) flag('robots.txt returns a server error', 'critical', [cfg.origin + '/robots.txt'], 'Google stops crawling a site whose robots.txt keeps failing.');
if (!sitemapInfo.found) flag('No sitemap.xml found at /sitemap.xml', 'important', [cfg.origin + '/sitemap.xml'], 'A sitemap helps Google find every page. (It may live at another address; check robots.txt.)');
else if (!sitemapInfo.declaredInRobotsTxt) flag('Sitemap not listed in robots.txt', 'nice-to-have', [cfg.origin + '/robots.txt'], 'Small fix that helps crawlers find it.');

return [{
  json: {
    brand: cfg.brandName,
    website: cfg.origin,
    pagesChecked: pages.length,
    sampleNote: `This is a sample of ${pages.length} pages (homepage, its links, then sitemap), not a full crawl.`,
    issues,
    crawlerAccess,
    sitemap: sitemapInfo,
    llmsTxt: ok(llms) ? 'present (informational only: no major AI engine has confirmed it uses llms.txt)' : 'not present (not a problem: llms.txt is unproven)',
    speed,
    homepageSchema: homeSchema || 'none',
    deliberatelyIgnored: [
      'meta keywords tag (Google ignores it)',
      'keyword density (not a ranking factor)',
      '"Domain Authority" scores (made up by SEO tool companies, not used by Google)',
      'HTML/W3C validation errors and text-to-HTML ratio',
      'sitemap priority/changefreq values (Google ignores them)',
    ],
    pages: pages.map(p => ({
      url: p.url, status: p.status, title: p.title, h1: p.h1, words: p.words,
      schema: p.schemaTypes, questionHeadings: p.questionHeadings, lastModified: p.lastModified,
    })),
  },
}];

