// Puts everything into one report: owner summary first, details after.
const cfg = $('2. Prepare Inputs').first().json;
const facts = $('11. Rule-Based Checks').first().json;
const review = $('13. Your Review (Human Checkpoint)').first().json;
const reviewed = review.reviewerNotes && !/^No human corrections yet/i.test(review.reviewerNotes);
const text = name => { try { return $(name).first().json.text || '(no output)'; } catch (e) { return '(step did not run)'; } };
const esc = s => String(s ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ');

const pageRows = facts.pages.map(p =>
  `| ${esc(p.url)} | ${p.status} | ${esc(p.title).slice(0, 60)} | ${p.words} | ${esc(p.schema) || '-'} |`).join('\n');
const botRows = facts.crawlerAccess.map(c => `| ${c.bot} | ${c.kind} | ${c.access} | ${esc(c.what)} |`).join('\n');

// Speed in plain words, e.g. "Loading (LCP): 3.9 s (AVERAGE)"
const sp = facts.speed;
const ru = sp.realUsers;
const speedLine = !sp.available ? sp.note
  : `Lab score (mobile, simulated): **${sp.labScore}/100**, main content loads in ${sp.labLCP}.\n\n` +
    (typeof ru === 'string' ? ru : 'Real visitors (last 28 days): ' + [
      ru.LCP_ms && `loading (LCP) ${(ru.LCP_ms.value / 1000).toFixed(1)} s (${ru.LCP_ms.rating})`,
      ru.INP_ms && `response to taps (INP) ${ru.INP_ms.value} ms (${ru.INP_ms.rating})`,
      ru.CLS_x100 && `layout jumps (CLS) ${(ru.CLS_x100.value / 100).toFixed(2)} (${ru.CLS_x100.rating})`,
    ].filter(Boolean).join(', ') + '.') + '\n\n' + sp.note;

const md = `# SEO & AEO Audit: ${cfg.brandName}

**Website:** ${cfg.origin}  
**Date:** ${new Date().toISOString().slice(0, 10)}  
**How this was made:** code collected the facts, AI wrote the analysis, ${reviewed ? 'a human reviewed and corrected it.' : '**human review not done yet** (draft).'}

---

## 1. Summary for the business owner

${text('15. AI Translator (Owner Summary)')}

---

## 2. Audit: what is wrong, in priority order

${text('12. AI Auditor')}

---

## 3. Human review notes

${reviewed ? review.reviewerNotes : '_Not reviewed yet. This is an unreviewed AI draft._'}

---

## 4. Content strategy

${text('14. AI Strategist')}

---

## Appendix A: Pages checked

${facts.sampleNote}

| URL | Status | Title | Words | Schema |
|---|---|---|---|---|
${pageRows}

## Appendix B: Who can read the site (robots.txt)

| Crawler | Type | Access | What it powers |
|---|---|---|---|
${botRows}

## Appendix C: Speed

${speedLine}

## Appendix D: Checked on purpose and ignored as noise

${facts.deliberatelyIgnored.map(x => '- ' + x).join('\n')}
`;

return [{ json: { reportMarkdown: md } }];

